import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"调整实用自动化配方","description":"","frontmatter":{"title":"调整实用自动化配方","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"965a59a41c6330f1329be6e35858a2984a01be9515d373ed184b0c4ae8be2f23","translationRevision":"748da8e1a2b19176f98f5c6be019c5c1ed2785b62f34a22839fab3e43480db79","order":30},"headers":[],"relativePath":"zh/user/automations/recipes.md","filePath":"zh/user/automations/recipes.md","lastUpdated":1795735295000}`),s={name:`zh/user/automations/recipes.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="adapt-practical-automation-recipes" tabindex="-1">调整实用自动化配方 <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to “调整实用自动化配方”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>将已验证的<a href="./first-rule.html">日志规则</a>改为精确匹配的响应。你需要当前配置以及已观察到的事件字段。先使用 <code>core.log</code> 操作；确认匹配及触发频率后，再换成其他效果。</p><h2 id="match-a-chat-command" tabindex="-1">匹配聊天命令 <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to “匹配聊天命令”">​</a></h2><p>创建 <code>tiktok.chat</code> 事件，条件为 <code>event.data.comment</code> 等于（<code>eq</code>）<code>!hello</code>。记录：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你好，{{ event.user.uniqueId }}</span></span></code></pre></div><p>使用 <code>30</code> 秒的按用户冷却，防止一位观众持续触发，同时保留其他观众的独立机会。命令适合精确相等匹配；包含匹配也会接受前后带其他文字的消息。请根据意图选择。</p><h2 id="record-a-qualifying-gift" tabindex="-1">记录符合条件的礼物 <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to “记录符合条件的礼物”">​</a></h2><p>创建 <code>tiktok.gift</code> 事件，条件为 <code>event.data.diamondCount</code> 大于或等于（<code>gte</code>）<code>10</code>。记录：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>收到 {{ event.user.uniqueId }} 送出的 {{ event.data.giftName }}</span></span></code></pre></div><p>先检查真实礼物详情。礼物钻石值、重复次数和完成标志是不同字段。如果需要仅在连送完成时响应，先确认收到的载荷提供 <code>event.data.repeatEnd</code>，再使用布尔值 true 条件。仅凭名称筛选，不能推断每次连送完成只执行一次。</p><h2 id="bound-a-shared-reaction" tabindex="-1">限制共享响应频率 <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to “限制共享响应频率”">​</a></h2><p>创建 <code>tiktok.follow</code> 事件，设置 <code>10</code> 秒全局冷却，并关联一个简短的日志操作。如果两位观众在该时间间隔内关注，全局冷却可能抑制后一次响应。需要每位观众分别享有触发额度时，改用按用户范围。</p><p>使用多个操作时，请排列好列表；每一步都必须执行时，保持全部操作模式。随机模式选择一个操作，不会随机排序并执行所有步骤。仅在后续步骤需要等待时添加 <code>core.delay</code>。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “预期结果与状态”">​</a></h2><p>本地引擎支持这些触发器、字段筛选和冷却控件。运行应对应一个被接受的匹配事件，并受冷却和启用状态约束。提供商特有的行为仍需通过真实直播验证。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to “恢复方法”">​</a></h2><p>配方失败时，请恢复到单个日志操作，查看载荷，并暂时简化条件。排查期间不要在繁忙直播中关闭限流。音频、积分、HTTP 和插件测试可能产生实际效果。添加这些依赖前，先检查<a href="./../plugins/audio.html">音频设置</a>、<a href="./variables.html">变量</a>和<a href="./../preferences/troubleshooting.html">运行诊断</a>。</p><p>在改动真实配置之前先交互式试用:</p>`,19),t(d,{scenario:`automation`,locale:`zh`,panel:`automation`,title:`试用自动化工作区`})])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};